<?php declare(strict_types=1); namespace App\Application\Arena\Service; use App\Application\Arena\DTO\Response\ArenaSubjectResponseDto; use App\Domain\Taxonomy\Repository\TaxonomySubjectRepositoryInterface; final class ListArenaSubjectsService { public function __construct(private readonly TaxonomySubjectRepositoryInterface $subjects){} public function list(int $page,int $perPage):array{$items=$this->subjects->list(($page-1)*$perPage,$perPage);$questionCounts=$this->subjects->questionCountsBySubjectId();return ["items"=>array_map(fn($subject)=>new ArenaSubjectResponseDto($subject->id,$subject->name,$subject->parentId,$questionCounts[$subject->id]??0),$items),"page"=>$page,"perPage"=>$perPage,"total"=>$this->subjects->count()];} }
